/** Observes real channels, including the source that fails before becoming a merge-heap member. */
class LmdbSortedRunsOwnershipTest {

	private static final int[] SPOC = { 0, 1, 2, 3 };
	private static final int[] OSPC = { 2, 0, 1, 3 };

	@TempDir
	Path directory;

	@Test
	void truncatedInitialReadClosesTheFailingChannelAndEarlierHeapInputs() throws Exception {
		Path valid = writeValidRun("valid.run");
		Path truncated = Files.write(directory.resolve("truncated.run"), new byte[31]);
		assertThat(Files.size(valid)).isEqualTo(64);
		assertThat(Files.size(truncated)).isEqualTo(31);
		try (ChannelObservation observation = new ChannelObservation(directory, null, null)) {
			IOException failure = assertThrows(IOException.class,
					() -> new LmdbSortedRuns.Merge(List.of(valid, truncated), SPOC, false));
			assertThat(failure.getClass()).isEqualTo(IOException.class);
			assertThat(failure).hasMessage("Truncated sorted run file");
			assertThat(observation.paths()).containsExactly(valid, truncated);
			observation.assertAllClosed();
		}
	}

	@Test
	void realTruncationRemainsPrimaryWhenClosingAnEarlierInputAlsoFails() throws Exception {
		Path valid = writeValidRun("valid-close-fails.run");
		Path truncated = Files.write(directory.resolve("truncated-after-valid.run"), new byte[31]);
		IOException cleanup = new IOException("retained channel cleanup sentinel");
		try (ChannelObservation observation = new ChannelObservation(directory, valid, cleanup)) {
			IOException failure = assertThrows(IOException.class,
					() -> new LmdbSortedRuns.Merge(List.of(valid, truncated), SPOC, false));
			assertThat(observation.cleanupCalls).as("the forwarding close fault was actually reached").isEqualTo(1);
			assertThat(failure.getClass()).isEqualTo(IOException.class);
			assertThat(failure).isNotSameAs(cleanup).hasMessage("Truncated sorted run file");
			assertThat(failure.getSuppressed()).hasSize(1);
			assertThat(failure.getSuppressed()[0]).isSameAs(cleanup);
			assertThat(observation.paths()).containsExactly(valid, truncated);
			observation.assertAllClosed();
		}
	}

	@Test
	void interruptedDuplicateOnlyMemoryMergeStopsBeforeConsumingTheEntirePhysicalRun() throws Exception {
		assertThat(Thread.currentThread().isInterrupted()).as("the test must not inherit another task's interrupt")
				.isFalse();
		int count = 8_192;
		long[] input = new long[count * 4];
		for (int row = 0; row < count; row++) {
			input[row * 4] = 1;
			input[row * 4 + 1] = 7;
			input[row * 4 + 2] = 11;
		}
		LmdbSortedRuns.Runs runs = new LmdbSortedRuns.Runs(List.of(),
				LmdbSortedRuns.sortInMemory(input, 0, count, SPOC));
		try (LmdbSortedRuns.Merge merge = new LmdbSortedRuns.Merge(runs, SPOC, true)) {
			long[] row = new long[4];
			assertThat(merge.next(row)).isTrue();
			assertThat(row).containsExactly(1L, 7L, 11L, 0L);
			assertThat(merge.duplicates()).isZero();
			Thread.currentThread().interrupt();
			try {
				assertThrows(InterruptedIOException.class, () -> merge.next(row));
				assertThat(Thread.currentThread().isInterrupted()).as("cancellation preserves the caller flag")
						.isTrue();
				assertThat(merge.duplicates()).as("physical duplicate consumption, not only emitted logical rows")
						.isLessThanOrEqualTo(1_024L);
			} finally {
				// Only this test's thread was interrupted; never pass its flag into unrelated tests or cleanup.
				Thread.interrupted();
			}
		}
	}

	@Test
	@Timeout(60)
	void realConsolidationBoundsOpenChannelsAndPreservesEveryDuplicateOnReplay() throws Exception {
		Path runsDirectory = Files.createDirectory(directory.resolve("consolidated"));
		List<List<Long>> expected = new ArrayList<>();
		try (ChannelObservation observation = new ChannelObservation(runsDirectory, null, null)) {
			try (LmdbRunCollector collector = new LmdbRunCollector("owned", runsDirectory,
					new int[][] { SPOC, OSPC }, 4, 1, Runnable::run)) {
				for (int i = 0; i < 520; i++) {
					long subject = i % 13;
					long object = i % 2 == 0 ? Long.MIN_VALUE + 1 : 19;
					collector.add(subject, 7, object, 0);
					collector.commit();
					expected.add(List.of(subject, 7L, object, 0L));
				}
				List<LmdbSortedRuns.Runs> completed = collector.completeRuns();
				assertThat(completed).hasSize(2);
				assertThat(collector.completeRuns()).isEqualTo(completed);
				assertThat(observation.paths()
						.stream()
						.filter(path -> path.getFileName().toString().startsWith("owned-merge-")))
								.as("real consolidation files were opened, not merely a smaller final list")
								.isNotEmpty();
				observation.assertAllClosed();
				for (int order = 0; order < completed.size(); order++) {
					int[] fields = order == 0 ? SPOC : OSPC;
					List<List<Long>> ordered = expected.stream().sorted(unsignedComparator(fields)).toList();
					assertThat(completed.get(order).files()).hasSizeLessThanOrEqualTo(32);
					for (int replay = 0; replay < 2; replay++) {
						List<List<Long>> actual = new ArrayList<>();
						try (LmdbSortedRuns.Merge merge = new LmdbSortedRuns.Merge(completed.get(order), fields,
								false)) {
							long[] row = new long[4];
							while (merge.next(row)) {
								actual.add(List.of(row[0], row[1], row[2], row[3]));
							}
							assertThat(merge.duplicates()).as("duplicate-preserving merges do not discard records")
									.isZero();
						}
						assertThat(actual).hasSize(520).isEqualTo(ordered);
						observation.assertAllClosed();
					}
				}
			}
			assertThat(observation.maximumOpen)
					.as("the actual peak reaches but never exceeds 32 input channels plus one output")
					.isEqualTo(33);
			observation.assertAllClosed();
		}
		try (var files = Files.list(runsDirectory)) {
			assertThat(files).as("terminal collector cleanup removes only its owned files").isEmpty();
		}
	}

	private Path writeValidRun(String name) throws IOException {
		ByteBuffer bytes = ByteBuffer.allocate(64);
		bytes.putLong(1).putLong(7).putLong(11).putLong(0);
		bytes.putLong(2).putLong(7).putLong(12).putLong(0);
		return Files.write(directory.resolve(name), bytes.array());
	}

	private static Comparator<List<Long>> unsignedComparator(int[] fields) {
		return (left, right) -> {
			for (int field : fields) {
				int comparison = Long.compareUnsigned(left.get(field), right.get(field));
				if (comparison != 0) {
					return comparison;
				}
			}
			return 0;
		};
	}

	/**
	 * Thread-local static observation follows both FileChannel.open overloads without double-counting delegation. Every
	 * retained channel is the real result of a successful native/filesystem open. Only one optional returned forwarding
	 * mock changes close: it first closes that real channel, then throws the exact cleanup sentinel.
	 */
	private static final class ChannelObservation implements AutoCloseable {
		private final List<Opened> opened = new ArrayList<>();
		private final MockedStatic<FileChannel> calls;
		private int openDepth;
		private long maximumOpen;
		private int cleanupCalls;

		ChannelObservation(Path root, Path closeFailurePath, IOException cleanup) {
			Path ownedRoot = root.toAbsolutePath().normalize();
			calls = mockStatic(FileChannel.class, invocation -> {
				if (!invocation.getMethod().getName().equals("open")) {
					return invocation.callRealMethod();
				}
				int previousDepth = openDepth++;
				try {
					FileChannel channel = (FileChannel) invocation.callRealMethod();
					Path path = invocation.getArgument(0);
					if (previousDepth != 0 || !path.toAbsolutePath().normalize().startsWith(ownedRoot)) {
						return channel;
					}
					opened.add(new Opened(path, channel));
					maximumOpen = Math.max(maximumOpen,
							opened.stream().filter(entry -> entry.channel.isOpen()).count());
					if (path.equals(closeFailurePath)) {
						Answer<Object> delegate = delegatesTo(channel);
						return mock(FileChannel.class, delegated -> {
							if (delegated.getMethod().getName().equals("close")) {
								channel.close();
								cleanupCalls++;
								throw cleanup;
							}
							return delegate.answer(delegated);
						});
					}
					return channel;
				} finally {
					openDepth = previousDepth;
				}
			});
		}

		List<Path> paths() {
			return opened.stream().map(Opened::path).toList();
		}

		void assertAllClosed() {
			for (Opened entry : opened) {
				assertThat(entry.channel.isOpen()).as("the real opened channel is closed: %s", entry.path).isFalse();
			}
		}

		@Override
		public void close() throws IOException {
			IOException failure = null;
			try {
				// Even a failing ownership assertion must not leak a real file descriptor into the next test.
				for (Opened entry : opened) {
					try {
						entry.channel.close();
					} catch (IOException cleanup) {
						if (failure == null) {
							failure = cleanup;
						} else {
							failure.addSuppressed(cleanup);
						}
					}
				}
			} finally {
				calls.close();
			}
			if (failure != null) {
				throw failure;
			}
		}
	}

	private record Opened(Path path, FileChannel channel) {
	}
}
